/// <summary>
///     The <c>AVAProdDateHistoryService</c> class is the service class for <c>AVAProdDateHistory</c>
/// </summary>
class AVAProdDateHistoryService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
///    AVA <c>runService</c> method.
/// </summary>
/// <param name="_contract">
///     <c>AVAProdDateHistoryContract</c> as type
/// </param>
void runService(AVAProdDateHistoryContract _contract)
{
    AVAProdDateHistoryContract  locAVAProdDateHistoryContract;
    Args                        locArgs;
    MenuFunction                locMenuFunction;

    #OCCRetryCount

    locAVAProdDateHistoryContract   = _contract as AVAProdDateHistoryContract;
    locArgs                         = locAVAProdDateHistoryContract.parmArgs();
    if(locArgs == null)
    {
        locArgs = new Args();
    }
    locArgs.parm(_contract.parmProdId());

    try
    {
        AVAProdDateHistoryCreateData::main(locArgs);
        if(!this.isExecutingInBatch())
        {
            locMenuFunction = new MenuFunction(menuItemDisplayStr(AVAProdDateHistoryDisplay), MenuItemType::Display);
            if (hasMenuItemSecurityAccess(locMenuFunction))
            {
                locMenuFunction.run(new Args());
            }
        }
    }

    catch (Exception::Deadlock)
    {
        retry;
    }

    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
